@* Summary statistics bar displayed at the top of the board *@

<div class="board-stats d-flex flex-wrap gap-3 p-3 mb-3 bg-light rounded">
    <div class="stat-item">
        <strong>Total:</strong> @Total
    </div>
    <div class="stat-item">
        <strong>To Do:</strong> @ToDo
    </div>
    <div class="stat-item">
        <strong>In Progress:</strong> @InProgress
    </div>
    <div class="stat-item">
        <strong>Done:</strong> @Done
    </div>
    <div class="stat-item text-danger">
        <strong>Overdue:</strong> @Overdue
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    private int Total => Tasks.Count;
    private int ToDo => Tasks.Count(t => t.Status == "To Do");
    private int InProgress => Tasks.Count(t => t.Status == "In Progress");
    private int Done => Tasks.Count(t => t.Status == "Done");
    private int Overdue => Tasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done");
}

@* Search input that filters tasks by title *@

<div class="mb-3">
    <input type="text"
           class="form-control"
           placeholder="Search tasks by title…"
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

